// =========================================================
// REGISTRO LOCAL DE USUARIOS — DEMO SIN BACKEND
// =========================================================
const USERS_KEY="control_salidas_v2_usuarios";
function loadUsers(){
  try{const v=JSON.parse(localStorage.getItem(USERS_KEY)||"[]");return Array.isArray(v)?v:[];}catch{return [];}
}
let users=loadUsers();
let pendingIne="";

function saveUsers(){localStorage.setItem(USERS_KEY,JSON.stringify(users));renderUsers();}
function userFullName(u){return `${u.nombres||""} ${u.apellidos||""}`.trim();}
function resetUserForm(){
  $("userForm").reset();
  $("editingUserIndex").value="-1";
  $("userFormTitle").textContent="Registrar usuario";
  $("saveUserBtn").textContent="Registrar usuario";
  $("cancelEditBtn").classList.add("hidden");
  $("inePreview").classList.add("hidden");
  $("inePreviewImg").removeAttribute("src");
  pendingIne="";
}
function renderUsers(){
  const list=$("usersList"), query=normalize($("userSearch")?.value||"");
  if(!list)return;
  const filtered=users.filter(u=>normalize([userFullName(u),u.matricula,u.grupo,u.especialidad,u.tutor].join(" ")).includes(query));
  $("userCountBadge").textContent=`${users.length} ${users.length===1?"usuario":"usuarios"}`;
  list.innerHTML="";
  if(!filtered.length){list.innerHTML=`<div class="empty-users">${users.length?"No hay coincidencias con la búsqueda.":"Todavía no hay usuarios registrados."}</div>`;return;}
  filtered.forEach(u=>{
    const realIndex=users.indexOf(u);
    const row=document.createElement("article");row.className="user-row";
    row.innerHTML=`<div class="user-main"><strong>${escapeHtml(userFullName(u))}</strong><div class="user-meta"><span>Matrícula: ${escapeHtml(u.matricula)}</span><span>${escapeHtml(u.semestre)}° semestre</span><span>${escapeHtml(u.grado)}° grado</span><span>Grupo ${escapeHtml(u.grupo)}</span><span>${escapeHtml(u.especialidad)}</span></div><div class="user-tutor">Tutor: ${escapeHtml(u.tutor)} ${u.ine?"· INE registrada":"· Sin INE"}</div></div><div class="user-actions"><button class="edit-user" data-index="${realIndex}" type="button">Modificar</button><button class="delete-user" data-index="${realIndex}" type="button">Dar de baja</button></div>`;
    list.appendChild(row);
  });
  list.querySelectorAll(".edit-user").forEach(btn=>btn.addEventListener("click",()=>editUser(Number(btn.dataset.index))));
  list.querySelectorAll(".delete-user").forEach(btn=>btn.addEventListener("click",()=>deleteUser(Number(btn.dataset.index))));
}
function editUser(index){
  const u=users[index];if(!u)return;
  $("editingUserIndex").value=String(index);
  $("uNombres").value=u.nombres||"";$("uApellidos").value=u.apellidos||"";$("uMatricula").value=u.matricula||"";
  $("uSemestre").value=u.semestre||"";$("uGrado").value=u.grado||"";$("uGrupo").value=u.grupo||"";$("uEspecialidad").value=u.especialidad||"";$("uTutor").value=u.tutor||"";
  pendingIne=u.ine||"";
  if(pendingIne){$("inePreviewImg").src=pendingIne;$("inePreview").classList.remove("hidden");}else{$("inePreview").classList.add("hidden");}
  $("userFormTitle").textContent="Modificar usuario";$("saveUserBtn").textContent="Guardar cambios";$("cancelEditBtn").classList.remove("hidden");
  $("uNombres").focus();
  window.scrollTo({top:0,behavior:"smooth"});
}
function deleteUser(index){
  const u=users[index];if(!u)return;
  if(!window.confirm(`¿Dar de baja a ${userFullName(u)}?`))return;
  users.splice(index,1);saveUsers();
  if(Number($("editingUserIndex").value)===index)resetUserForm();
  showToast("Usuario dado de baja");
}
$("uIne").addEventListener("change",()=>{
  const file=$("uIne").files[0];if(!file)return;
  if(file.size>3*1024*1024){showToast("La imagen del INE supera los 3 MB.");$("uIne").value="";return;}
  const reader=new FileReader();reader.onload=()=>{pendingIne=reader.result;$("inePreviewImg").src=pendingIne;$("inePreview").classList.remove("hidden");};reader.readAsDataURL(file);
});
$("removeIneBtn").addEventListener("click",()=>{pendingIne="";$("uIne").value="";$("inePreviewImg").removeAttribute("src");$("inePreview").classList.add("hidden");});
$("cancelEditBtn").addEventListener("click",resetUserForm);
$("userSearch").addEventListener("input",renderUsers);
$("userForm").addEventListener("submit",e=>{
  e.preventDefault();
  const index=Number($("editingUserIndex").value);
  const record={nombres:$("uNombres").value.trim(),apellidos:$("uApellidos").value.trim(),matricula:$("uMatricula").value.trim(),semestre:$("uSemestre").value,grado:$("uGrado").value,grupo:$("uGrupo").value.trim(),especialidad:$("uEspecialidad").value.trim(),tutor:$("uTutor").value.trim(),ine:pendingIne||""};
  if(!record.nombres||!record.apellidos||!record.matricula||!record.semestre||!record.grado||!record.grupo||!record.especialidad||!record.tutor){showToast("Completa todos los campos del usuario.");return;}
  const duplicate=users.findIndex((u,i)=>normalize(u.matricula)===normalize(record.matricula)&&i!==index);
  if(duplicate!==-1){showToast("La matrícula ya está registrada.");return;}
  if(index>=0&&index<users.length){users[index]=record;showToast("Usuario modificado correctamente");}else{users.push(record);showToast("Usuario registrado correctamente");}
  saveUsers();resetUserForm();
});

document.querySelectorAll(".records-tab").forEach(btn=>btn.addEventListener("click",()=>{
  const view=btn.dataset.recordsView;
  document.querySelectorAll(".records-tab").forEach(b=>b.classList.toggle("active",b===btn));
  $("usersRecordsView").classList.toggle("active-records-view",view==="users");
  $("authorizedRecordsView").classList.toggle("active-records-view",view==="authorized");
  if(view==="authorized")renderRegistry();
}));
